import { g as getEmpresaId } from "../../../../../chunks/get-empresa-id.js";
import { d as db } from "../../../../../chunks/db.js";
import { fail } from "@sveltejs/kit";
import "../../../../../chunks/formData.js";
import { s as superValidate, z as zod, m as message } from "../../../../../chunks/zod.js";
import { c as categoriaSchema } from "../../../../../chunks/index4.js";
const load = async ({ request }) => {
  const empresaId = await getEmpresaId(request);
  const categorias = await db.categoria.findMany({
    where: { empresaId },
    include: {
      _count: {
        select: {
          produtos: true
        }
      }
    }
  });
  const form = await superValidate(zod(categoriaSchema));
  return { categorias, form };
};
const actions = {
  create: async ({ request }) => {
    const form = await superValidate(request, zod(categoriaSchema));
    const empresaId = await getEmpresaId(request);
    if (!form.valid) {
      return fail(400, { form });
    }
    try {
      await db.categoria.create({
        data: {
          ...form.data,
          empresaId
        }
      });
      return message(form, "Categoria criado com sucesso!");
    } catch (error) {
      console.error("Error creating supplier:", error);
      return fail(500, {
        form,
        error: "Erro ao criar Categoria"
      });
    }
  },
  edit: async ({ request, url }) => {
    const form = await superValidate(request, zod(categoriaSchema));
    const id = url.searchParams.get("id");
    if (!id) {
      return fail(400, { form, error: "ID do Categoria não fornecido" });
    }
    if (!form.valid) {
      return fail(400, { form });
    }
    try {
      await db.categoria.update({
        where: { id },
        data: form.data
      });
      return message(form, "Categoria atualizado com sucesso!");
    } catch (error) {
      console.error("Error updating supplier:", error);
      return fail(500, {
        form,
        error: "Erro ao atualizar Categoria"
      });
    }
  }
};
export {
  actions,
  load
};
